// ──────────────────────────── types ──────────────────────────────────────

class Recent
{
    private readonly string[] _slots;
    private int _next;   // where the next Add writes
    private int _count;  // saturates at capacity

    public Recent(int capacity)
    {
        _slots = new string[capacity];
    }

    public void Add(string item)
    {
        _slots[_next] = item;
        _next = (_next + 1) % _slots.Length;
        if (_count < _slots.Length) _count++;
    }

    public List<string> Items()
    {
        var start = (_next - _count + _slots.Length) % _slots.Length;
        var items = new List<string>(_count);
        for (int i = 0; i < _count; i++)
            items.Add(_slots[(start + i) % _slots.Length]);
        return items;
    }
}

