// ─────────────────────────────────────────────────────────────────────────
//  03 · top k                                                  ★★☆ core
//  concepts: counting · deterministic tie-break
// ─────────────────────────────────────────────────────────────────────────
//
//  "Top 10 endpoints by hits" — and when two endpoints tie, the order must
//  be the same on every run, every machine, every test.

using static Bootcamp.Check;

List<string> TopK(List<string> events, int k)
{
    var counts = new Dictionary<string, int>();
    foreach (var e in events)
        counts[e] = counts.GetValueOrDefault(e) + 1;
    return counts
        .OrderByDescending(kv => kv.Value)
        .ThenBy(kv => kv.Key, StringComparer.Ordinal)
        .Take(k)
        .Select(kv => kv.Key)
        .ToList();
}

