// ──────────────────────────── types ──────────────────────────────────────

class WindowCounter
{
    private readonly int _window;
    private readonly int _limit;
    private readonly Queue<long> _hits = new(); // calls arrive with non-decreasing atSeconds

    public WindowCounter(int windowSeconds, int limit)
    {
        _window = windowSeconds;
        _limit = limit;
    }

    public bool TryHit(long atSeconds)
    {
        while (_hits.Count > 0 && _hits.Peek() <= atSeconds - _window)
            _hits.Dequeue();
        if (_hits.Count >= _limit) return false;
        _hits.Enqueue(atSeconds);
        return true;
    }
}

