// ──────────────────────────── types ──────────────────────────────────────

class TokenBucket
{
    private readonly int _capacity;
    private readonly int _rate;
    private long _tokens;
    private long _lastRefillAt;

    public TokenBucket(int capacity, int refillPerSecond)
    {
        _capacity = capacity;
        _rate = refillPerSecond;
        _tokens = capacity;   // starts full
        _lastRefillAt = 0;    // construction time is 0
    }

    public bool TryTake(long atSeconds)
    {
        _tokens = Math.Min(_capacity, _tokens + (atSeconds - _lastRefillAt) * _rate);
        _lastRefillAt = atSeconds;
        if (_tokens == 0) return false;
        _tokens--;
        return true;
    }
}

