// ──────────────────────────── types ──────────────────────────────────────

class History
{
    private readonly Stack<string> _done = new();
    private readonly Stack<string> _undone = new();

    public void Push(string state)
    {
        _done.Push(state);
        _undone.Clear(); // history has branched: the old future is gone
    }

    public string? Undo()
    {
        if (!_done.TryPop(out var state)) return null;
        _undone.Push(state);
        return state;
    }

    public string? Redo()
    {
        if (!_undone.TryPop(out var state)) return null;
        _done.Push(state);
        return state;
    }
}
